// fiber/radio/nodes/<addr>: {"addr":"0x1a2b3c4d","name":"button:0",...}, retained, or an empty
// message when the node was removed (docs/mqtt-api.md, "The radio"). The names are kept for the
// other function nodes of this flow.
const addr = msg.topic.split("/")[3];
const names = flow.get("names") || {};
const info = msg.payload;
if (info && typeof info === "object" && info.name) {
    names[addr] = info.name;
} else {
    delete names[addr];
}
flow.set("names", names);
return null;

// A request to the agent (docs/mqtt-api.md, "Requests"): a new id every time, as the agent
// drops one it has seen. The mqtt out node sends it on fiber/cmd, never retained.
const ask = (op, params) => ({
    payload: { id: "node-red-" + Date.now() + "-" + Math.random().toString(36).slice(2, 10), op, params },
});

// fiber/radio/nodes/<addr>/event/button: {"value":"click","count":42,"counter":1234,"ts":...}.
// QoS 1 can bring one twice: the counter grows for each node, so one already seen is dropped.
const addr = msg.topic.split("/")[3];
const e = msg.payload;
if (!e || e.value !== "click") {
    return null;
}
const seen = flow.get("counters") || {};
if (seen[addr] !== undefined && e.counter <= seen[addr]) {
    return null;
}
seen[addr] = e.counter;
flow.set("counters", seen);
const name = (flow.get("names") || {})[addr] || addr;
return [[
    ask("display.message", { text: name + "\nclicked", seconds: 5 }),
    ask("buzzer.beep", { pattern: "double" }),
]];

// fiber/radio/nodes/<addr>/state/temperature/<member>: {"value":21.5,"ts":...}. Each of a node's
// thermometers is one member of the group "temperature" (temperature/system is the Core Module's).
const parts = msg.topic.split("/");
const addr = parts[3];
const member = parts.slice(6).join("/");
const name = (flow.get("names") || {})[addr] || addr;
if (!msg.payload || typeof msg.payload !== "object") {
    return null;
}
msg.payload = name + " " + member + ": " + msg.payload.value + " °C";
return msg;
